"""Regenerate internal/pycompat/unicode.txt, errno_linux.txt and testdata/fixtures.json.

Run from the repository root: python3 -I internal/pycompat/testdata/gen.py

unicode.txt holds the per-code-point str predicates the Go package cannot take from its own
stdlib tables (a different Unicode version may ship with Go). Each line is a record kind and
space-separated hex ranges lo-hi:
  A str.isalpha   D str.isdecimal   G str.isdigit   N str.isnumeric
  P str.isprintable
str.isspace is internal/textfold's IsSpace (its unicode.txt "s" record).
isalnum is A|D|G|N and re's \\w on str patterns is isalnum or '_' (checked by a digest).
The case records are CPython's per-character flags, probed through the str methods:
  U upper (ch.isupper())   L lower (ch.islower())
  T title or both upper and lower (neither ch+"A" isupper nor ch+"a" islower)
  C cased (ch+"a").title() keeps the "a"   I case-ignorable (the final-sigma probe)
and the full mappings cp:cp.cp... of the single character where they differ:
  u ch.upper()   t ch.title()
str.lower() is internal/textfold's Lower.

errno_linux.txt holds this Linux Python's os.strerror(n) ("E n text", omitted when it is
"Unknown error n") and the OSError subclass Python raises for errno n ("K n Class", omitted
for OSError itself). testdata/gen_windows.py writes the Windows counterpart.

fixtures.json holds the outputs of the real Python operations the Go functions reproduce,
one case per line, plus SHA-256 digests over every non-surrogate code point. Typed values
are [kind, value] pairs: none, bool, int (decimal text), float (IEEE bits as hex), str,
list (of typed values), tuple (of typed values).
"""
import hashlib
import html
import io
import json
import math
import os
import posixpath
import random
import re
import struct
import sys
import unicodedata

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.dirname(HERE)


def chars():
    return (chr(c) for c in range(0x110000) if not 0xD800 <= c <= 0xDFFF)


def ranges(pred):
    out, start, prev = [], None, None
    for ch in chars():
        c = ord(ch)
        if pred(ch):
            if start is None or c != prev + 1:
                if start is not None:
                    out.append((start, prev))
                start = c
            prev = c
    if start is not None:
        out.append((start, prev))
    return out


def pack(kind, entries, width=200):
    lines, cur = [], kind
    for e in entries:
        if len(cur) + 1 + len(e) > width and cur != kind:
            lines.append(cur)
            cur = kind
        cur += " " + e
    if cur != kind:
        lines.append(cur)
    return lines


PREDICATES = {"A": str.isalpha, "D": str.isdecimal, "G": str.isdigit, "N": str.isnumeric,
              "P": str.isprintable}


SIGMA, FINAL = "\u03a3", "\u03c2"
CASE = {"U": str.isupper, "L": str.islower,
        "T": lambda ch: not (ch + "A").isupper() and not (ch + "a").islower(),
        "C": lambda ch: (ch + "a").title()[-1] == "a",
        "I": lambda ch: ("A" + ch + SIGMA).lower()[-1] == FINAL and (ch + SIGMA).lower()[-1] != FINAL}
MAPS = {"u": str.upper, "t": str.title}


def seq(s):
    return ".".join("%04X" % ord(c) for c in s)


def write_unicode():
    lines = ["# generated by internal/pycompat/testdata/gen.py: Python %s, Unicode %s; do not edit"
             % (sys.version.split()[0], unicodedata.unidata_version)]
    for kind, pred in list(PREDICATES.items()) + list(CASE.items()):
        lines += pack(kind, ["%04X-%04X" % r for r in ranges(pred)])
    for kind, fn in MAPS.items():
        lines += pack(kind, ["%04X:%s" % (ord(ch), seq(fn(ch))) for ch in chars() if fn(ch) != ch])
    with open(os.path.join(PKG, "unicode.txt"), "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + "\n")


def write_errno():
    lines = ["# generated by internal/pycompat/testdata/gen.py: Python %s on %s; do not edit"
             % (sys.version.split()[0], sys.platform)]
    lines += ["E %d %s" % (n, os.strerror(n)) for n in range(256) if os.strerror(n) != "Unknown error %d" % n]
    lines += ["K %d %s" % (n, type(OSError(n, "x")).__name__) for n in range(256)
              if type(OSError(n, "x")) is not OSError]
    with open(os.path.join(PKG, "errno_linux.txt"), "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + "\n")


def os_errors():
    """[errno, strerror, filename, filename2, str(e), class] of real and constructed OSErrors;
    the filenames are os.fsencode() bytes in hex (a Go path is those bytes)."""
    out = []
    for f in (lambda: open("/nonexistent-pycompat/x"), lambda: os.rename("/nonexistent-pycompat/a", "/nonexistent-pycompat/b"),
              lambda: os.listdir("/proc/self/fd/0/x"), lambda: open("/", "w"), lambda: os.rmdir("/proc")):
        try:
            f()
        except OSError as e:
            out.append(e)
    names = ["p", "it's", 'say "hi"', "tab\t", "\u00e9", os.fsdecode(b"bad\xff\xfe")]
    for i, n in enumerate([1, 2, 13, 17, 20, 21, 39, 84, 104, 110, 200]):
        out.append(OSError(n, os.strerror(n), names[i % len(names)]))
    out.append(OSError(2, os.strerror(2), "a", None, "b'c"))
    out.append(OSError(5, os.strerror(5)))
    fs = lambda f: None if f is None else os.fsencode(f).hex()
    return [[e.errno, e.strerror, fs(e.filename), fs(e.filename2), str(e), type(e).__name__] for e in out]


NEWLINES = ["", "a", "a\n", "a\r\nb", "a\rb", "a\n\rb", "a\r\r\nb", "\r", "\r\n", "\n\n", "trailing\r",
            "x\x0by\x0cz\x1cw", "a\x85b\u2028c\u2029d\n", "mixed\r\nlines\rand\nmore", "\r\r\n\n\r"]


def file_lines(s):
    """(read(), list(iter())) of a text file holding s, opened with newline=None."""
    data = s.encode("utf-8")
    with io.TextIOWrapper(io.BytesIO(data), encoding="utf-8", newline=None) as fh:
        text = fh.read()
    with io.TextIOWrapper(io.BytesIO(data), encoding="utf-8", newline=None) as fh:
        return [text, list(fh)]


def digest(parts):
    h = hashlib.sha256()
    for p in parts:
        h.update(p.encode("utf-8"))
        h.update(b"\n")
    return h.hexdigest()


def bits(f):
    return "%016x" % struct.unpack(">Q", struct.pack(">d", f))[0]


def typed(v):
    if v is None:
        return ["none"]
    if isinstance(v, bool):
        return ["bool", v]
    if isinstance(v, int):
        return ["int", str(v)]
    if isinstance(v, float):
        return ["float", bits(v)]
    if isinstance(v, str):
        return ["str", v]
    if isinstance(v, list):
        return ["list", [typed(x) for x in v]]
    if isinstance(v, tuple):
        return ["tuple", [typed(x) for x in v]]
    raise TypeError(v)


def attempt(f, *a):
    try:
        return f(*a)
    except (ValueError, TypeError, KeyError, OverflowError):
        return None


