FORMAT_VALUES = ["", "a", "ab", "h\u00e9llo", "\u65e5\u672c\u8a9e", "e\u0301", "\U0001f600x", "a longer string value",
                 0, 1, -1, 5, 42, -42, 65, 255, 1234, -1234567, 1000000007, 2 ** 63, 2 ** 70, -(2 ** 70), 0x10FFFF,
                 0x110000, True, False, None, 10 ** 400]
FORMAT_FLOATS = [0.0, -0.0, 0.1, 0.5, 1.0, -1.5, 2.5, 1 / 3, 0.125, 1234.5678, -1234.5678, 999.9996, 0.0001234, 1e-5,
                 1e-7, 1e15, 9999999999999998.0, 1e16, 1.2345678901234568e17, 123456789.0, 1e100, 5e-324,
                 1.7976931348623157e308, -0.0004, float("inf"), float("-inf"), float("nan"), -float("nan")]


def py_format(v, spec):
    try:
        return format(v, spec)
    except (ValueError, TypeError, OverflowError) as e:
        return [type(e).__name__, str(e)]


def float_path(v, spec):
    """True when format(v, spec) runs CPython's float formatter: v is a float, or an int (bool
    included) whose spec ends in a float presentation type (int.__format__ converts it)."""
    return isinstance(v, float) or (isinstance(v, int) and spec != "" and spec[-1] in "eEfFgG%")


# The format(value, spec) cases are generated goldens under testdata/golden/, one per formatter,
# so each one travels with the Go code it checks. Each holds the Python version, its typed values
# and one [spec, results] row per spec; a result is the str or [exception class, message], and
# null marks a pair that belongs to the other formatter's golden.
def format_golden(values, keep):
    return {"python": sys.version.split()[0], "values": [typed(v) for v in values],
            "format": [[spec, [py_format(v, spec) if keep(v, spec) else None for v in values]]
                       for spec in FORMAT_SPECS]}


JOINS = [["a", "b"], ["a/", "b"], ["a", "/b", "c"], ["", "a"], ["a", ""], ["/", "x"], ["a", "b/", "c"]]


def case_context(ch):
    """The multi-character paths of the case methods around ch, joined with '|'."""
    flags = "%d%d%d%d" % ((ch + "A").isupper(), (ch + "a").islower(), (ch + "ab").istitle(), ("A" + ch).istitle())
    return "|".join([flags, ("a" + ch + "b").title(), ("A" + ch + SIGMA).swapcase(), ("x" + ch).capitalize(),
                     (ch + SIGMA + "a").title(), ("A" + SIGMA + ch).capitalize()])


def float_samples():
    rnd = random.Random(20261017)
    out = list(FLOATS)
    for _ in range(400):
        out.append(struct.unpack(">d", struct.pack(">Q", rnd.getrandbits(64)))[0])
    for _ in range(200):
        out.append(round(rnd.uniform(-1e6, 1e6), rnd.randint(0, 6)))
    return out


def write_json(path, out):
    """out as JSON with one list row per line."""
    with open(path, "w", encoding="utf-8") as fh:
        fh.write("{\n")
        keys = list(out)
        for i, k in enumerate(keys):
            v = out[k]
            sep = "," if i < len(keys) - 1 else ""
            if isinstance(v, list):
                fh.write(" %s: [\n" % json.dumps(k))
                fh.write(",\n".join("  " + json.dumps(row, ensure_ascii=False) for row in v))
                fh.write("\n ]%s\n" % sep)
            else:
                fh.write(" %s: %s%s\n" % (json.dumps(k), json.dumps(v, ensure_ascii=False, sort_keys=True), sep))
        fh.write("}\n")


def main():
    sys.dont_write_bytecode = True
    write_unicode()
    write_errno()
    word = re.compile(r"\w")
    floats = float_samples()
    out = {
        "python": sys.version.split()[0],
        "unicode": unicodedata.unidata_version,
        "repr": [[typed(v), repr(v), str(v)] for v in STRINGS + FLOATS[:8] +
                 [None, True, False, 0, -12, 10 ** 20, ["a", 1, None, 2.5], ("one",), ("K", "V"), (), []]],
        "float": [[bits(f), repr(f), "%g" % f, json.dumps(f), attempt(lambda x: str(int(x)), f)] for f in floats],
        "parse_int": [[s, attempt(lambda x: str(int(x)), s)] for s in INT_TEXTS],
        "parse_float": [[s, attempt(lambda x: bits(float(x)), s)] for s in FLOAT_TEXTS],
        "percent": [[fmt, {k: typed(v) for k, v in params.items()}, attempt(lambda: fmt % params)]
                    for fmt, params in PERCENT],
        "decode": [[b.hex(), b.decode("utf-8", "replace")] for b in DECODE],
        "lines": [[s, s.splitlines(), s.splitlines(True)] for s in LINES],
        "spaces": [[s, s.strip(), s.split()] for s in SPACES],
        "html": [[s, html.escape(s), html.unescape(s)] for s in HTML],
        "paths": [[p, posixpath.basename(p), posixpath.splitext(p)[0]] for p in PATHS],
        "joins": [[parts, posixpath.join(*parts)] for parts in JOINS],
        "case": [[c, c.isupper(), c.islower(), c.istitle(), c.upper(), c.lower(), c.title(), c.capitalize(),
                  c.swapcase()] for c in CASES],
        "just": [[s, f, [[s.ljust(w, f), s.rjust(w, f), s.center(w, f)] for w in WIDTHS]]
                 for s in JUST for f in FILLS],
        "cut": [[s, [s[:n] for n in range(-8, 9)]] for s in CUTS],
        "os_errors": os_errors(),
        "strerror": [[n, os.strerror(n)] for n in (-1, 0, 1, 2, 13, 84, 133, 134, 200, 255, 256, 4000)],
        "newlines": [[s] + file_lines(s) for s in NEWLINES],
        "digests": {
            "alpha": digest(ch for ch in chars() if ch.isalpha()),
            "decimal": digest(ch for ch in chars() if ch.isdecimal()),
            "digit": digest(ch for ch in chars() if ch.isdigit()),
            "numeric": digest(ch for ch in chars() if ch.isnumeric()),
            "alnum": digest(ch for ch in chars() if ch.isalnum()),
            "printable": digest(ch for ch in chars() if ch.isprintable()),
            "space": digest(ch for ch in chars() if ch.isspace()),
            "word": digest(ch for ch in chars() if word.match(ch)),
            "linebreak": digest(ch for ch in chars() if len(("a" + ch + "b").splitlines()) == 2),
            "repr": digest(repr(ch) for ch in chars()),
            "decimal_value": digest(ch + str(int(ch)) for ch in chars() if ch.isdecimal()),
            "isupper": digest(ch for ch in chars() if ch.isupper()),
            "islower": digest(ch for ch in chars() if ch.islower()),
            "istitle": digest(ch for ch in chars() if ch.istitle()),
            "upper": digest(ch.upper() for ch in chars()),
            "title": digest(ch.title() for ch in chars()),
            "capitalize": digest(ch.capitalize() for ch in chars()),
            "swapcase": digest(ch.swapcase() for ch in chars()),
            "case_context": digest(case_context(ch) for ch in chars()),
        },
    }
    write_json(os.path.join(HERE, "fixtures.json"), out)
    os.makedirs(os.path.join(HERE, "golden"), exist_ok=True)
    write_json(os.path.join(HERE, "golden", "format_str_int.golden"),
               format_golden(FORMAT_VALUES, lambda v, spec: not float_path(v, spec)))
    write_json(os.path.join(HERE, "golden", "format_float.golden"),
               format_golden(FORMAT_FLOATS + [v for v in FORMAT_VALUES if isinstance(v, int)], float_path))
    print("unicode.txt, errno_linux.txt and fixtures.json written", file=sys.stderr)


if __name__ == "__main__":
    main()
